import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";
import { FontLoader, Font } from "three/examples/jsm/loaders/FontLoader";

const ThreeTextPage = () => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let camera: THREE.PerspectiveCamera,
      scene: THREE.Scene,
      renderer: THREE.WebGLRenderer;

    function init() {
      // Camera
      camera = new THREE.PerspectiveCamera(
        45,
        window.innerWidth / window.innerHeight,
        1,
        10000
      );
      camera.position.set(0, -400, 600);

      // Scene
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0xf0f0f0);

      // Font Loader
      const loader = new FontLoader();
      loader.load("fonts/helvetiker_regular.typeface.json", (font: Font) => {
        const color = 0x006699;

        const matDark = new THREE.LineBasicMaterial({
          color: color,
          side: THREE.DoubleSide,
        });

        const matLite = new THREE.MeshBasicMaterial({
          color: color,
          transparent: true,
          opacity: 0.4,
          side: THREE.DoubleSide,
        });

        const message = "   Three.js\nSimple text.";
        const shapes = font.generateShapes(message, 100);
        const geometry = new THREE.ShapeGeometry(shapes);

        geometry.computeBoundingBox();
        const xMid =
          -0.5 * (geometry.boundingBox!.max.x - geometry.boundingBox!.min.x);
        geometry.translate(xMid, 0, 0);

        // Make shape
        const text = new THREE.Mesh(geometry, matLite);
        text.position.z = -150;
        scene.add(text);

        // Make line shape
        const holeShapes: THREE.Shape[] = [];

        shapes.forEach((shape) => {
          if (shape.holes && shape.holes.length > 0) {
            shape.holes.forEach((hole: any) => holeShapes.push(hole));
          }
        });

        shapes.push(...holeShapes);
        const lineText = new THREE.Object3D();

        shapes.forEach((shape) => {
          const points = shape.getPoints();
          const lineGeometry = new THREE.BufferGeometry().setFromPoints(points);
          lineGeometry.translate(xMid, 0, 0);

          const lineMesh = new THREE.Line(lineGeometry, matDark);
          lineText.add(lineMesh);
        });

        scene.add(lineText);

        render();
      });

      // Renderer
      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setPixelRatio(window.devicePixelRatio);
      renderer.setSize(window.innerWidth, window.innerHeight);
      if (mountRef.current) {
        mountRef.current.appendChild(renderer.domElement);
      }

      // Controls
      const controls = new OrbitControls(camera, renderer.domElement);
      controls.target.set(0, 0, 0);
      controls.update();
      controls.addEventListener("change", render);

      window.addEventListener("resize", onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      render();
    }

    function render() {
      renderer.render(scene, camera);
    }

    init();

    return () => {
      window.removeEventListener("resize", onWindowResize);
      if (mountRef.current) {
        mountRef.current.removeChild(renderer.domElement);
      }
    };
  }, []);

  return <div ref={mountRef} />;
};

export default ThreeTextPage;
